    @Test void recordsOneApplicationWhenNotificationUnconfigured() throws Exception {
        exportPopulation37();
        JsonNode analysis=success("{}");
        assertEquals(37,analysis.path("n").asInt());
        String id=analysis.path("analysisId").asText();
        MvcResult denied=xlsx("{\"source\":\"COHORT\",\"analysisId\":\""+id+"\"}");
        assertEquals(409,denied.getResponse().getStatus());
        JsonNode need=json.readTree(denied.getResponse().getContentAsByteArray());
        assertEquals("NEED_APPLY",need.path("code").asText());
        assertEquals(15,need.path("data").path("requested").size());
        String digest=sourceDigest();byte[] original=analysisPayload(id);int writes=context.getBean(ObservedWriter.class).completed;int audits=rawCount("SELECT COUNT(*) FROM ra_ai_export_audit");
        String request="{\"requestId\":\"00000000-0000-4000-8000-000000000001\",\"export\":{\"source\":\"COHORT\",\"analysisId\":\""+id+"\",\"fields\":"+need.path("data").path("requested")+"},\"startDate\":\"2026-01-01\",\"endDate\":\"2026-10-07\",\"purposeCode\":\"RESEARCH\",\"reason\":\"本地说明=姓名/病例-CANARY\"}";
        MvcResult result=http.perform(post("/api/ra/export/applyAnalysis").contentType("application/json").content(request)).andReturn();
        assertEquals(200,result.getResponse().getStatus(),result.getResponse().getContentAsString());
        JsonNode data=json.readTree(result.getResponse().getContentAsByteArray()).path("data");
        assertTrue(Long.parseLong(data.path("applicationId").asText())>0);
        assertEquals("APPLICATION_RECORDED",data.path("status").asText());
        assertEquals("FAILED",data.path("notification").path("mailStatus").asText());
        assertEquals("NOT_CONFIGURED",data.path("notification").path("reason").asText());
        assertEquals(1,rawCount("SELECT COUNT(*) FROM export_application WHERE doctor_id=101 AND doctor_name IS NULL AND mail_sent=0 AND mail_to IS NULL AND status='pending'"));
        assertEquals(1,rawCount("SELECT COUNT(*) FROM ra_ai_export_request WHERE application_id="+data.path("applicationId").asText()+" AND mail_state='FAILED' AND attempt_no=1 AND last_error='NOT_CONFIGURED'"));
        assertEquals(digest,sourceDigest());assertArrayEquals(original,analysisPayload(id));assertEquals(writes,context.getBean(ObservedWriter.class).completed);assertEquals(audits,rawCount("SELECT COUNT(*) FROM ra_ai_export_audit"));
        exited();
    }
