    @Test void committedApplicationSendsOneSafeRealMimeAfterDatabaseExit()throws Exception {
        exportPopulation37();String reference=success("{}").path("analysisId").asText();String body=request(reference,"00000000-0000-4000-8000-000000000002","[\"patientId\",\"sex\"]");
        try(NotificationSmtpPeer peer=new NotificationSmtpPeer(NotificationSmtpPeer.Mode.SUCCESS)){
            smtp(peer);String digest=sourceDigest();byte[] original=analysisPayload(reference);int audits=rawCount("SELECT COUNT(*) FROM ra_ai_export_audit");
            peer.onConnect=()->{assertEquals(0,applicationObserved.active.get());try{assertEquals(1,rawCount("SELECT COUNT(*) FROM ra_ai_export_request r JOIN export_application a ON a.id=r.application_id WHERE r.mail_state='UNKNOWN' AND r.attempt_no=1 AND r.attempt_id IS NOT NULL AND a.mail_sent=0"));}catch(Exception e){throw new AssertionError(e);}};
            MvcResult response=apply(body);assertEquals(200,response.getResponse().getStatus());JsonNode data=json.readTree(response.getResponse().getContentAsByteArray()).path("data");
            assertEquals("SENT",data.path("notification").path("mailStatus").asText());assertTrue(data.path("notification").path("smtpAccepted").asBoolean());assertEquals("UNKNOWN",data.path("notification").path("deliveryStatus").asText());
            assertEquals(1,peer.connections.get());assertEquals(1,peer.accepted.get());assertEquals(1,peer.messages.size());assertNull(peer.failure);
            javax.mail.internet.MimeMessage message=new javax.mail.internet.MimeMessage(javax.mail.Session.getInstance(new java.util.Properties()),new java.io.ByteArrayInputStream(peer.messages.get(0)));
            String app=data.path("applicationId").asText();assertEquals("RA导出申请 #"+app,message.getSubject());assertTrue(message.getContentType().toLowerCase().startsWith("text/plain"));assertTrue(message.getContentType().toLowerCase().contains("utf-8"));assertEquals("<ra-export-"+app+"@notification.invalid>",message.getMessageID());assertEquals("sender@notification.invalid",((javax.mail.internet.InternetAddress)message.getFrom()[0]).getAddress());assertEquals("admin@notification.invalid",((javax.mail.internet.InternetAddress)message.getAllRecipients()[0]).getAddress());assertEquals(1,message.getAllRecipients().length);
            String text=(String)message.getContent();assertEquals("申请编号："+app+"\n申请医生ID：101\n用途：研究分析\n申请日期范围：2026-01-01 至 2026-10-07\n结果类型：COHORT\n结果引用："+reference+"\n引用人数：37\n申请字段：patientId,sex\n通知说明：此邮件仅记录导出申请，不表示审批通过或历史文件已生成。\n",text.replace("\r\n","\n"));assertFalse(text.contains("CANARY"));assertNull(message.getDisposition());
            assertEquals(1,rawCount("SELECT COUNT(*) FROM ra_ai_export_request r JOIN export_application a ON a.id=r.application_id WHERE r.mail_state='SENT' AND a.mail_sent=1 AND a.status='pending'"));assertEquals(audits,rawCount("SELECT COUNT(*) FROM ra_ai_export_audit"));assertEquals(0,context.getBean(ObservedWriter.class).completed);assertEquals(digest,sourceDigest());assertArrayEquals(original,analysisPayload(reference));
            assertEquals(200,apply(body).getResponse().getStatus());assertEquals(1,peer.connections.get());exited();
        }
    }
