    @Test void canonicalReplayAndConflictPrecedeExpiryAndCurrentScope()throws Exception {
        exportPopulation37();String reference=success("{}").path("analysisId").asText(),body=basic(reference,10);JsonNode original=data(apply(body));String id=original.path("applicationId").asText();
        com.fasterxml.jackson.databind.node.ObjectNode shuffled=(com.fasterxml.jackson.databind.node.ObjectNode)json.readTree(body);((com.fasterxml.jackson.databind.node.ObjectNode)shuffled.get("export")).set("fields",json.readTree("[\"sex\",\"patientId\"]"));shuffled.put("reason","  本地说明=姓名/病例-CANARY  ");java.util.List<String> keys=new java.util.ArrayList<>();shuffled.fieldNames().forEachRemaining(keys::add);java.util.Collections.reverse(keys);com.fasterxml.jackson.databind.node.ObjectNode reordered=json.createObjectNode();for(String k:keys)reordered.set(k,shuffled.get(k));String canonical=json.writerWithDefaultPrettyPrinter().writeValueAsString(reordered);
        clock.now=clock.now.plusSeconds(86400);sql("DELETE FROM patient_relation_doctor");resetOwners();assertEquals(id,data(apply(canonical)).path("applicationId").asText());assertEquals(0,observed.scopeReads);assertEquals(1,rawCount("SELECT COUNT(*) FROM export_application"));assertEquals(1,rawCount("SELECT COUNT(*) FROM ra_ai_export_request WHERE attempt_no=1"));
        for(String changed:new String[]{body.replace("姓名/病例","姓名 /病例"),body.replace("patientId\",\"sex","age\",\"sex"),body.replace("2026-01-01","2026-01-02"),body.replace("RESEARCH","OTHER"),body.replace(reference,"00000000-0000-4000-8000-000000000088")}){resetOwners();MvcResult r=apply(changed);assertEquals(409,r.getResponse().getStatus());assertEquals("IDEMPOTENCY_CONFLICT",json.readTree(r.getResponse().getContentAsByteArray()).path("code").asText());assertEquals(0,observed.scopeReads);}
        assertEquals(410,apply(body.replace("000000000010","000000000011")).getResponse().getStatus());exited();
    }
