    @Test void acceptedSmtpThenSettleRollbackRemainsUnknownAndRetryCannotDuplicate()throws Exception {
        exportPopulation37();String reference=success("{}").path("analysisId").asText(),body=basic(reference,100);
        try(NotificationSmtpPeer peer=new NotificationSmtpPeer(NotificationSmtpPeer.Mode.SUCCESS)){smtp(peer);applicationObserved.afterSqlContains="SET mail_state=?";java.util.concurrent.atomic.AtomicBoolean reached=new java.util.concurrent.atomic.AtomicBoolean();applicationObserved.afterSql=(owner,sql)->{reached.set(true);try(java.sql.Statement st=owner.createStatement();java.sql.ResultSet r=st.executeQuery("SELECT COUNT(*) FROM ra_ai_export_request r JOIN export_application a ON a.id=r.application_id WHERE r.mail_state='SENT' AND a.mail_sent=1")){assertTrue(r.next());assertEquals(1,r.getInt(1));}assertEquals(0,rawCount("SELECT COUNT(*) FROM export_application WHERE mail_sent=1"));throw new java.sql.SQLException("synthetic accepted-settle rollback","45000");};JsonNode first=data(apply(body));String id=first.path("applicationId").asText();assertTrue(reached.get());assertEquals("UNKNOWN",first.path("notification").path("mailStatus").asText());assertFalse(first.path("notification").path("statusConfirmed").asBoolean());assertTrue(first.path("notification").path("smtpAccepted").asBoolean());assertEquals(1,peer.accepted.get());assertEquals(1,rawCount("SELECT COUNT(*) FROM ra_ai_export_request WHERE mail_state='UNKNOWN'"));assertEquals(0,rawCount("SELECT COUNT(*) FROM export_application WHERE mail_sent=1"));JsonNode retried=data(retry(id));assertEquals(1,peer.connections.get(),"UNKNOWN必须不再次连接SMTP");assertEquals(1,peer.messages.size(),"UNKNOWN必须不产生第二封邮件");assertEquals("UNKNOWN",retried.path("notification").path("mailStatus").asText());assertEquals(id,data(apply(body)).path("applicationId").asText());assertEquals(1,peer.connections.get());exited();}
    }

    @Test void dataAndFinalAckUncertaintyNeverPermitOrdinaryRetryOrReplay()throws Exception {
        exportPopulation37();String reference=success("{}").path("analysisId").asText();int sequence=110;
        for(NotificationSmtpPeer.Mode mode:new NotificationSmtpPeer.Mode[]{NotificationSmtpPeer.Mode.DATA_SILENT,NotificationSmtpPeer.Mode.ACK_DROP})try(NotificationSmtpPeer peer=new NotificationSmtpPeer(mode)){
            smtp(peer);String body=basic(reference,sequence++);java.util.concurrent.atomic.AtomicReference<MvcResult> returned=new java.util.concurrent.atomic.AtomicReference<>();java.util.concurrent.atomic.AtomicReference<Throwable> failure=new java.util.concurrent.atomic.AtomicReference<>();java.util.concurrent.atomic.AtomicBoolean flag=new java.util.concurrent.atomic.AtomicBoolean();java.util.concurrent.CountDownLatch done=new java.util.concurrent.CountDownLatch(1);Thread caller=new Thread(()->{try{returned.set(apply(body));flag.set(Thread.currentThread().isInterrupted());}catch(Throwable e){failure.set(e);}finally{done.countDown();}},"synthetic-apply-caller");caller.start();assertTrue(peer.waiting.await(3,java.util.concurrent.TimeUnit.SECONDS));assertEquals(0,applicationObserved.active.get());Object sender=context.getBean(com.wenwen.ai.export.mail.ExportNotificationSender.class);java.lang.reflect.Field active=sender.getClass().getDeclaredField("active");active.setAccessible(true);Object flight=((java.util.concurrent.atomic.AtomicReference<?>)active.get(sender)).get();java.lang.reflect.Field exit=flight.getClass().getDeclaredField("exited");exit.setAccessible(true);java.util.concurrent.CountDownLatch exited=(java.util.concurrent.CountDownLatch)exit.get(flight);
            int borrowed=applicationObserved.borrowed.get();long start=System.nanoTime();if(mode==NotificationSmtpPeer.Mode.DATA_SILENT)caller.interrupt();assertTrue(done.await(mode==NotificationSmtpPeer.Mode.DATA_SILENT?500:10500,java.util.concurrent.TimeUnit.MILLISECONDS));if(mode==NotificationSmtpPeer.Mode.DATA_SILENT){assertTrue(flag.get());assertEquals(borrowed,applicationObserved.borrowed.get(),"中断不清flag补JDBC");assertTrue(peer.eof.await(Math.max(0,java.util.concurrent.TimeUnit.MILLISECONDS.toNanos(500)-(System.nanoTime()-start)),java.util.concurrent.TimeUnit.NANOSECONDS));}else assertTrue(peer.eof.await(500,java.util.concurrent.TimeUnit.MILLISECONDS));assertEquals(0,exited.getCount());assertNull(failure.get());JsonNode d=data(returned.get());String id=d.path("applicationId").asText();assertEquals("UNKNOWN",d.path("notification").path("mailStatus").asText());assertFalse(d.path("notification").path("retryable").asBoolean());assertTrue(d.path("notification").path("smtpAccepted").isNull());assertEquals(1,peer.dataCommands.get());assertEquals(mode==NotificationSmtpPeer.Mode.ACK_DROP?1:0,peer.messages.size());assertEquals("UNKNOWN",data(retry(id)).path("notification").path("mailStatus").asText());assertEquals(id,data(apply(body)).path("applicationId").asText());assertEquals(1,peer.connections.get());assertEquals(1,rawCount("SELECT COUNT(*) FROM ra_ai_export_request WHERE application_id="+id+" AND mail_state='UNKNOWN' AND attempt_no=1"));assertEquals(0,rawCount("SELECT COUNT(*) FROM export_application WHERE id="+id+" AND mail_sent=1"));assertNull(peer.failure);exited();
        }
    }
    @Test void recipientBindingCannotSilentlyChangeAndPendingCanBeExplicitlyClaimed()throws Exception {
        exportPopulation37();String reference=success("{}").path("analysisId").asText();String body=basic(reference,120);JsonNode first=data(apply(body));String id=first.path("applicationId").asText();assertEquals("NOT_CONFIGURED",first.path("notification").path("reason").asText());
        try(NotificationSmtpPeer peer=new NotificationSmtpPeer(NotificationSmtpPeer.Mode.RCPT_REJECT)){smtp(peer);assertEquals("PRE_DATA_REJECTED",data(retry(id)).path("notification").path("reason").asText());assertEquals(1,peer.connections.get());context.close();analysisProperties.put("ra.export.apply-mail-to","changed@notification.invalid");buildContext(true);resetOwners();assertEquals("RECIPIENT_CHANGED",data(retry(id)).path("notification").path("reason").asText());assertEquals(1,peer.connections.get());assertEquals(1,rawCount("SELECT COUNT(*) FROM export_application WHERE id="+id+" AND mail_to='admin@notification.invalid'"));context.close();analysisProperties.put("ra.export.apply-mail-to","admin@notification.invalid");buildContext(true);resetOwners();peer.mode=NotificationSmtpPeer.Mode.SUCCESS;assertEquals("SENT",data(retry(id)).path("notification").path("mailStatus").asText());assertEquals(2,peer.connections.get());assertEquals(1,peer.messages.size());exited();}
        context.close();analysisProperties.put("ra.export.smtp.enabled","false");buildContext(true);resetOwners();String second=basic(reference,121);applicationObserved.failCommitAfter="SET application_id=";assertEquals(503,apply(second).getResponse().getStatus());JsonNode pending=data(apply(second));assertEquals("PENDING",pending.path("notification").path("mailStatus").asText());assertTrue(pending.path("notification").path("retryable").asBoolean());assertEquals("FAILED",data(retry(pending.path("applicationId").asText())).path("notification").path("mailStatus").asText());exited();
    }
    @Test void responseWriteFailureKeepsApplicationAndSmtpFactsOnReplay()throws Exception {
        exportPopulation37();String reference=success("{}").path("analysisId").asText(),body=basic(reference,130);
        try(NotificationSmtpPeer peer=new NotificationSmtpPeer(NotificationSmtpPeer.Mode.SUCCESS)){smtp(peer);OutputCut cut=new OutputCut(0,false,false);http=org.springframework.test.web.servlet.setup.MockMvcBuilders.webAppContextSetup(context).addFilters(bodyRead,cut).build();assertThrows(Exception.class,()->apply(body));assertTrue(cut.failed);assertEquals(1,peer.messages.size());assertEquals(1,rawCount("SELECT COUNT(*) FROM ra_ai_export_request r JOIN export_application a ON a.id=r.application_id WHERE r.mail_state='SENT' AND a.mail_sent=1"));http=org.springframework.test.web.servlet.setup.MockMvcBuilders.webAppContextSetup(context).addFilters(bodyRead).build();assertEquals("SENT",data(apply(body)).path("notification").path("mailStatus").asText());assertEquals(1,peer.connections.get());assertEquals(1,rawCount("SELECT COUNT(*) FROM export_application"));exited();}
    }
